-- @ Q4.1 effective grants of every kind in os: aclexplode(coalesce(acl, acldefault(kind, owner))) — kind | object | grantee (0=PUBLIC) | privilege | grantable | grantor | acl stored?
select k, obj, case grantee when 0 then 'PUBLIC' else pg_catalog.pg_get_userbyid(grantee) end, privilege_type, is_grantable, pg_catalog.pg_get_userbyid(grantor), stored from (
  select 'schema' k, n.nspname::text obj, (pg_catalog.aclexplode(coalesce(n.nspacl, pg_catalog.acldefault('n', n.nspowner)))).*, n.nspacl is not null stored from pg_catalog.pg_namespace n where n.nspname = 'os'
  union all select case c.relkind when 'S' then 'sequence' else 'relation' end, c.oid::regclass::text, (pg_catalog.aclexplode(coalesce(c.relacl, pg_catalog.acldefault(case when c.relkind = 'S' then 's' else 'r' end::"char", c.relowner)))).*, c.relacl is not null from pg_catalog.pg_class c where c.relnamespace = 'os'::regnamespace and c.relkind in ('r','v','S')
  union all select 'column', a.attrelid::regclass::text || '.' || a.attname, (pg_catalog.aclexplode(a.attacl)).*, true from pg_catalog.pg_attribute a join pg_catalog.pg_class c on c.oid = a.attrelid where c.relnamespace = 'os'::regnamespace and a.attacl is not null
  union all select 'function', p.oid::regprocedure::text, (pg_catalog.aclexplode(coalesce(p.proacl, pg_catalog.acldefault('f', p.proowner)))).*, p.proacl is not null from pg_catalog.pg_proc p where p.pronamespace = 'os'::regnamespace
  union all select 'type', t.oid::regtype::text, (pg_catalog.aclexplode(coalesce(t.typacl, pg_catalog.acldefault('T', t.typowner)))).*, t.typacl is not null from pg_catalog.pg_type t where t.typnamespace = 'os'::regnamespace and t.typtype in ('e','d') 
  union all select 'database', d.datname::text, (pg_catalog.aclexplode(coalesce(d.datacl, pg_catalog.acldefault('d', d.datdba)))).*, d.datacl is not null from pg_catalog.pg_database d where d.datname = current_database()
) x order by 1, 2, 3, 4;
-- @ Q4.1b types made with a table/view (row types) and arrays: typacl is null; acldefault('T', owner) gives PUBLIC USAGE
select t.oid::regtype::text, t.typtype, t.typacl is null as acl_null, pg_catalog.acldefault('T', t.typowner)::text from pg_catalog.pg_type t where t.typnamespace = 'os'::regnamespace order by 1;
-- @ Q4.2 who may CONNECT to this database: has_database_privilege for the five roles (CONNECT comes from PUBLIC)
select r, pg_catalog.has_database_privilege(r, current_database(), 'connect'), pg_catalog.has_database_privilege(r, current_database(), 'create'), pg_catalog.has_database_privilege(r, current_database(), 'temporary') from unnest(array['os_owner','os_engine','os_executor','os_intake','os_reader']) r;
-- @ Q4.3 pg_default_acl: every row whose role is one of the five, or whose grantee is (a row's absence means the built-in default: acldefault)
select pg_catalog.pg_get_userbyid(d.defaclrole), coalesce(d.defaclnamespace::regnamespace::text, '(all schemas)'), d.defaclobjtype, d.defaclacl::text from pg_catalog.pg_default_acl d where pg_catalog.pg_get_userbyid(d.defaclrole) like 'os\_%' or d.defaclacl::text ~ 'os_(owner|engine|executor|intake|reader)' order by 1,2,3;
-- @ Q4.3b the platform's own default ACLs (count by role), which the chain's objects in os do NOT get (they apply to objects made BY that role)
select pg_catalog.pg_get_userbyid(d.defaclrole), count(*) from pg_catalog.pg_default_acl d group by 1 order by 1;
-- @ Q6a pg_shdepend: every row naming one of the five roles — database (0 = shared), catalogue, object, deptype (o owner, a acl, r policy, i init acl)
select coalesce((select datname from pg_catalog.pg_database where oid = s.dbid), '(shared)') as db, s.classid::regclass::text, coalesce((select i.type || ' ' || i.identity from pg_catalog.pg_identify_object(s.classid, s.objid, s.objsubid) i), '(another database: oid ' || s.objid || ')'), s.deptype, pg_catalog.pg_get_userbyid(s.refobjid) from pg_catalog.pg_shdepend s where s.refclassid = 'pg_catalog.pg_authid'::regclass and pg_catalog.pg_get_userbyid(s.refobjid) like 'os\_%' order by 5, 1, 3;
-- @ Q6a.2 what pg_shdepend does NOT carry for the five roles: memberships (pg_auth_members) and role settings (pg_db_role_setting) — read where they live
select 'membership', pg_catalog.pg_get_userbyid(roleid), pg_catalog.pg_get_userbyid(member), pg_catalog.pg_get_userbyid(grantor) from pg_catalog.pg_auth_members where pg_catalog.pg_get_userbyid(roleid) like 'os\_%' or pg_catalog.pg_get_userbyid(member) like 'os\_%' order by 2,3,4;
-- @ Q6.runner what the runner leaves outside os: os_chain's owner and grants
select n.nspname, pg_catalog.pg_get_userbyid(n.nspowner), n.nspacl::text, (select c.relacl::text from pg_catalog.pg_class c where c.oid = 'os_chain.ledger'::regclass), (select pg_catalog.pg_get_userbyid(relowner) from pg_catalog.pg_class where oid = 'os_chain.ledger'::regclass), (select count(*) from pg_catalog.pg_class where relnamespace = n.oid) as relations from pg_catalog.pg_namespace n where n.nspname = 'os_chain';
-- @ Q6.runner-b who may read/write the ledger (has_table_privilege)
select r, pg_catalog.has_table_privilege(r, 'os_chain.ledger', 'select'), pg_catalog.has_table_privilege(r, 'os_chain.ledger', 'insert') from unnest(array['postgres','os_owner','os_reader','anon','authenticated','service_role','supabase_read_only_user']) r;
